'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {JSDOM}=require('jsdom');
const {verifyProfile}=require('./verify.cjs');
const {gunzipSync}=require('node:zlib');
const legacy=path.join(__dirname,'authors/');
const KEY='data-study-compiled-key',read=n=>{const file=path.join(__dirname,n);return fs.existsSync(file)?fs.readFileSync(file,'utf8'):gunzipSync(fs.readFileSync(file+'.gz')).toString('utf8')},settle=()=>new Promise(r=>setImmediate(r));
function fixture(name,change=()=>{},options={}){const html=read(name+'/final.html'),raw=read(name+'/profile.json'),anchors=JSON.parse(read(name+'/anchors.json'));const profile=verifyProfile(raw,html,anchors,options.isCurrent);const dom=new JSDOM(html,{runScripts:'outside-only',url:'https://card.invalid'}),win=dom.window,doc=win.document;win.PointerEvent=win.MouseEvent;win.eval(fs.readFileSync(legacy+'sense-filter.js','utf8'));win.__ankiExamSourceReader='full-paper';win.eval(read('original-author-library.js'));win.eval(fs.readFileSync(legacy+'author-chunks.js','utf8'));change(doc,profile);win.eval(read('runtime.js'));let invalid=null;const runtime=options.noRuntime?null:win.AnkiCompiledCardRuntime.install(doc,profile,{isCurrent:options.isCurrent||(()=>true),onInvalid:e=>{invalid=e}});win.eval(read('original-residual.js'));win.AnkiResidualReviewedChunkRuntime.install(doc);if(runtime)doc.addEventListener('click',event=>{const button=event.target.closest?.('[data-sf-filter]');if(button){const panel=button.closest('.sf-panel');try{runtime.applyGrouping(panel)}catch(_){} }},true);const key=id=>doc.querySelector(`[${KEY}="${id}"]`);const target=key(profile.projectionWrappers.find(k=>key(k).getAttribute('data-chunk-side')==='en'));const fire=(type,node,props={})=>{const event=type==='keydown'?new win.KeyboardEvent(type,{bubbles:true,cancelable:true,...props}):new win.MouseEvent(type,{bubbles:true,cancelable:true,...props});if(props.alreadyPrevented)event.preventDefault();if('pointerType'in props)Object.defineProperty(event,'pointerType',{value:props.pointerType});node.dispatchEvent(event);return event};return{win,doc,profile,runtime,target,key,fire,invalid:()=>invalid,close(){runtime?.dispose();win.close()}};}
function active(f){return [...f.doc.querySelectorAll('.card-chunk-active')].map(n=>n.textContent);}
function invariant(f){return{en:[...f.doc.querySelectorAll('.sf-en,.example-text')].map(n=>n.textContent),zh:[...f.doc.querySelectorAll('.sf-zh,.example-translation')].map(n=>n.textContent),frequency:[...f.doc.querySelectorAll('.frequency-count,.sf-count')].map(n=>n.textContent),audits:[...f.doc.querySelectorAll('.sf-group-member-evidence')].map(n=>n.innerHTML),bank:[...f.doc.querySelectorAll('[data-shared-reading-bank-evidence]')].map(n=>n.outerHTML)}};
for(const name of ['abolish','train'])test(name+' real compiled wrappers preserve 16 original interaction boundaries',async()=>{const f=fixture(name,undefined,{noRuntime:process.env.NO_RUNTIME==='1'});try{const before=invariant(f),target=f.target;assert(target);const root=target.closest('.example-card'),paired=()=>[...root.querySelectorAll('.card-chunk-active')];
 f.fire('pointerover',target,{pointerType:'mouse'});assert(paired().length>=2);f.fire('pointerout',target,{relatedTarget:f.doc.body});assert.equal(active(f).length,0);
 for(const pointerType of ['touch','pen']){f.fire('pointerover',target,{pointerType});assert.equal(active(f).length,0)}
 const tap=f.fire('click',target);assert(tap.defaultPrevented);const selected=active(f);f.fire('pointerout',target,{relatedTarget:f.doc.body});assert.deepEqual(active(f),selected);f.fire('click',target);assert.equal(active(f).length,0);
 for(const key of ['Enter',' ']){assert(f.fire('keydown',target,{key}).defaultPrevented,'owned wrapper keyboard must bridge');assert(active(f).length>=2);f.fire('keydown',target,{key:'Escape'});assert.equal(active(f).length,0)}
 for(const props of [{key:'Enter',ctrlKey:true},{key:'Enter',altKey:true},{key:' ',metaKey:true},{key:' ',repeat:true},{key:'x'}]){assert.equal(f.fire('keydown',target,props).defaultPrevented,false);assert.equal(active(f).length,0)}
 f.fire('keydown',target,{key:'Enter',alreadyPrevented:true});assert.equal(active(f).length,0);
 f.fire('click',target);const link=f.doc.querySelector('.sentence-jump');assert(link);assert.equal(f.fire('click',link).defaultPrevented,false);assert.equal(active(f).length,0);
 const summary=f.doc.querySelector('.sf-sense>summary');assert.equal(f.fire('keydown',summary,{key:' '}).defaultPrevented,false);
 const controls=f.doc.querySelectorAll('[data-sf-filter]');for(const button of controls){f.fire('click',target);f.fire('click',button);assert.equal(active(f).length,0);assert.equal(f.invalid(),null);}
 const fake=f.doc.createElement('span');fake.className='card-chunk';fake.dataset.chunkIds='1';fake.dataset.chunkSide='en';f.doc.body.append(fake);assert.equal(f.fire('keydown',fake,{key:'Enter'}).defaultPrevented,false);fake.remove();
 assert.deepEqual(invariant(f),before);assert.equal(f.runtime.refresh(),true);assert.equal(f.invalid(),null);
 }finally{f.close()}});
test('train real 3 physical targets merged to one row with three complete audit members and two Bank labels',()=>{const f=fixture('train');try{const group=f.profile.groups[0],members=group.memberKeys.map(f.key),first=members[0],proof=JSON.parse(fs.readFileSync(path.join(__dirname,'train/group-merge-proof.json')));assert.equal(members.length,3);assert.equal(first.dataset.sfGroupOccurrences,'3');assert.deepEqual(members.map(n=>n.hidden),[false,true,true]);assert.equal(first.querySelectorAll('.sf-group-member-evidence').length,3);for(const a of proof.audit_nodes){const node=f.key(a.key)||[...first.querySelectorAll('.sf-reason')].find(n=>n.outerHTML===a.after_html);assert(node);assert.equal(node.outerHTML,a.after_html)}assert.equal(first.querySelectorAll(':scope>.sf-sentence-pair .sf-en mark.target-word').length,3);assert.equal(f.profile.bankRecords.length,2);for(const b of f.profile.bankRecords)assert.equal(f.key(b.labelKey).getAttribute('data-shared-reading-bank-evidence'),b.evidence);const panel=f.key(group.panelKey);for(const button of panel.querySelectorAll('[data-sf-filter]')){f.fire('click',button);assert.equal(f.invalid(),null);const year=button.dataset.sfFilter;assert.deepEqual(members.map((n,i)=>n.hidden),members.map((n,i)=>i>0||(year!=='all'&&n.dataset.sfYear!==year)));assert.equal(first.dataset.sfGroupOccurrences,'3');} }finally{f.close()}});
test('external anchor SHA/schema/cancellation rejects before install or DOM writes',()=>{const html=read('abolish/final.html'),raw=read('abolish/profile.json'),a=JSON.parse(read('abolish/anchors.json'));for(const invoke of [()=>verifyProfile(raw+' ',html,a),()=>verifyProfile(raw,html+' ',a),()=>verifyProfile(raw,html,{...a,version:2}),()=>verifyProfile(raw,html,a,()=>false)])assert.throws(invoke,/Compiled/)});
test('missing duplicate moved key or wrong semantic attributes refuses without writes',()=>{for(const mutate of [(d,p)=>d.querySelector(`[${KEY}="${p.projectionWrappers[0]}"]`).removeAttribute(KEY),(d,p)=>{const n=d.querySelector(`[${KEY}="${p.projectionWrappers[0]}"]`);n.parentElement.append(n.cloneNode(true))},(d,p)=>{const n=d.querySelector(`[${KEY}="${p.projectionWrappers[0]}"]`);n.parentElement.append(n)},(d,p)=>d.querySelector(`[${KEY}="${p.projectionWrappers[0]}"]`).setAttribute('data-chunk-ids','999')])assert.throws(()=>fixture('abolish',mutate),/Compiled card invalid/)});
test('refresh rejects new semantic slot and preserves outside edits through dispose',async()=>{const f=fixture('train');try{const status=f.key(f.profile.panels[0].statusKey),member=f.key(f.profile.groups[0].memberKeys[1]);const foreign=f.doc.createElement('em');foreign.textContent='external';status.append(foreign);member.setAttribute('hidden','external-hidden');assert.throws(()=>f.runtime.refresh(),/external|semantic/);f.runtime.dispose();assert.equal(foreign.parentNode,status);assert.equal(member.getAttribute('hidden'),'external-hidden');}finally{f.close()}const g=fixture('abolish');try{assert.throws(()=>g.runtime.refresh({id:'new-slot'}),/not covered/);}finally{g.close()}});
test('semantic edits invalidate rather than recomputing or overwriting; cancelled runtime does not act',async()=>{let current=true;const f=fixture('abolish',undefined,{isCurrent:()=>current});try{const before=f.doc.body.innerHTML;current=false;assert.equal(f.fire('keydown',f.target,{key:'Enter'}).defaultPrevented,false);assert(f.invalid());assert.equal(f.doc.body.innerHTML,before);}finally{f.close()}const g=fixture('train');try{const extra=g.doc.createElement('span');extra.textContent='new';g.target.parentElement.append(extra);assert.throws(()=>g.runtime.refresh(),/semantic/);assert(extra.isConnected);assert.equal(g.runtime.stats().invalid!==null,true);}finally{g.close()}});
module.exports={fixture,invariant,active};

test('preflight bad role/schema/cancel/missing key has zero DOM writes and no installed listener',()=>{
 for(const kind of ['role','schema','cancel','missing']){
  const f=fixture('abolish',undefined,{noRuntime:true});
  try{const profile=JSON.parse(JSON.stringify(f.profile));if(kind==='role')profile.nodeBindings.find(n=>n.key===profile.projectionWrappers[0]).roles=[];if(kind==='schema')profile.version=2;if(kind==='missing')f.target.removeAttribute(KEY);const before=f.doc.body.innerHTML;assert.throws(()=>f.win.AnkiCompiledCardRuntime.install(f.doc,profile,{isCurrent:()=>kind!=='cancel'}),/Compiled card invalid/);assert.equal(f.doc.body.innerHTML,before);assert.equal(f.fire('keydown',f.target,{key:'Enter'}).defaultPrevented,false);}finally{f.close()}
 }
});
for(const name of ['abolish','train'])test(name+' real original source-reader change and translation label clicks survive MO microtasks',async()=>{const f=fixture(name);try{const selector=f.doc.querySelector('.source-reader');assert(selector);const immutable=f.profile.readerLinks.map(spec=>[spec.rootKey,spec.relativePath,spec.immutableAttrs]);for(const choice of ['latex','full-paper']){selector.value=choice;selector.dispatchEvent(new f.win.Event('change',{bubbles:true}));await settle();assert.equal(f.invalid(),null);assert.equal(f.runtime.refresh(),true);for(const spec of f.profile.readerLinks){let node=f.key(spec.rootKey);for(const i of spec.relativePath)node=node.childNodes[i];assert.equal(node.getAttribute('href'),node.getAttribute(choice==='latex'?'data-latex-url':'data-full-paper-url'));}assert.deepEqual(f.profile.readerLinks.map(spec=>[spec.rootKey,spec.relativePath,spec.immutableAttrs]),immutable);}const label=f.doc.querySelector('.translate-tag');assert(label);const text=label.parentElement.textContent,outer=label.parentElement.outerHTML;for(let n=0;n<2;n++){f.fire('click',label);await settle();assert.equal(f.invalid(),null);assert.equal(f.runtime.refresh(),true);assert.equal(label.parentElement.textContent,text);assert.equal(label.parentElement.outerHTML,outer);}}finally{f.close()}});
test('reader URL outside exact choices or immutable source tuple change invalidates after MO',async()=>{for(const kind of ['href','tuple']){const f=fixture('abolish');try{const spec=f.profile.readerLinks.find(s=>f.key(s.rootKey).matches('li')),root=f.key(spec.rootKey);let node=root;for(const i of spec.relativePath)node=node.childNodes[i];node.setAttribute(kind==='href'?'href':'data-latex-url','https://foreign.invalid/not-original');await settle();assert(f.invalid());assert.throws(()=>f.runtime.refresh(),/reader|semantic/);assert.equal(node.getAttribute(kind==='href'?'href':'data-latex-url'),'https://foreign.invalid/not-original');}finally{f.close()}}});
